diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..cd5c06e
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,34 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { app, fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+
+test("cooking bechamel takes soonest-expiring milk lot HD-1022 before HD-1026", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("consume follows FEFO: earliest expiry, no-expiry last, then receivedOn, then id", () => {
+  const store = fresh();
+  store.data.batches = [
+    { id: 10, itemId: 4, lot: "NO-EXP-LATE", qty: 1, receivedOn: "2026-10-05", expires: null, location: "dry" },
+    { id: 11, itemId: 4, lot: "NO-EXP-EARLY", qty: 1, receivedOn: "2026-10-01", expires: null, location: "dry" },
+    { id: 12, itemId: 4, lot: "LATER-EXP-OLDER-RECV", qty: 1, receivedOn: "2026-10-01", expires: "2026-11-10", location: "dry" },
+    { id: 15, itemId: 4, lot: "TIE-EXP-ID-HIGH", qty: 1, receivedOn: "2026-10-10", expires: "2026-11-05", location: "dry" },
+    { id: 13, itemId: 4, lot: "TIE-EXP-ID-LOW", qty: 1, receivedOn: "2026-10-10", expires: "2026-11-05", location: "dry" },
+    { id: 14, itemId: 4, lot: "TIE-EXP-EARLIER-RECV", qty: 1, receivedOn: "2026-10-08", expires: "2026-11-05", location: "dry" },
+    { id: 16, itemId: 4, lot: "SOONEST-EXP-NEWEST-RECV", qty: 1, receivedOn: "2026-10-27", expires: "2026-10-30", location: "dry" },
+  ];
+  const used = consume(store, 4, 7, { at, ref: "fefo" });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [16, 14, 13, 15, 12, 11, 10],
+  );
+});
